-- 角色控制器依赖的全局唯一 LeftJoystick, 因为是 ui元素, 所以塞到 UIRootCanvas 中去


local Singleton = import('Frame.Singleton')

---@class LeftJoystickCanvasMgr : Singleton
---@field GetInstance fun(self:LeftJoystickCanvasMgr):LeftJoystickCanvasMgr
local LeftJoystickCanvasMgr = Class("LeftJoystickCanvasMgr", Singleton)

-- 外部访问时使用:
-- local LeftJoystickCanvasMgr = import('Game.DreamSpace.UI.LeftJoystickCanvasMgr'):GetInstance()


-- ========================================================

--- lua:

local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

local DreamSpaceLuaUtils = import('Game.DreamSpace.Tools.DreamSpaceLuaUtils')
---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Transform = CS.UnityEngine.Transform
local Button = CS.UnityEngine.UI.Button
local RectTransform = CS.UnityEngine.RectTransform
local Vector3 = CS.UnityEngine.Vector3
local Vector2 = CS.UnityEngine.Vector2


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool


local DreamSpaceUtils = CS.DreamSpace.DreamSpaceUtils
local UIRootCanvas = CS.Engine.UI.UIRootCanvas

local ETCJoystick = CS.ETCJoystick

---@type Engine.Modules.ResourceModule
local ResourceModule = CS.Engine.Modules.ResourceModule


-- ========================================================


function LeftJoystickCanvasMgr:__init()
    self.rootCanvas = nil
    self.leftJoystickEnv = nil -- ETCJoystick Env
end


function LeftJoystickCanvasMgr:__delete()
    self.rootCanvas = nil
    self.leftJoystickEnv = nil -- ETCJoystick Env
end


-- =========================================== public ================================================ --


-- 若是找不到, 就初始化一个; 
function LeftJoystickCanvasMgr:CheckOrInitSync(joystickSize, position)

    if checkNumber(joystickSize) == 0 then
        joystickSize = 800
    end

    if isNull(self.rootCanvas) then 

        local RoleControllerRootCanvasMgr = import('Game.DreamSpace.UI.RoleControllerRootCanvasMgr'):GetInstance()
        RoleControllerRootCanvasMgr:CheckOrInitSync()
        local parentRectTF = RoleControllerRootCanvasMgr.rootCanvas.transform:Find("Root"):GetComponent(typeof(RectTransform))

        ---
        local path = "DreamSpace/Gameplay/LeftJoystickCanvas.prefab"
        local loader = ResourceModule.LoadBundleSync(path, nil, true)
        if isNotNull(loader) and loader.IsSuccess==true then 

            local newgo = Object.Instantiate( loader.ResultObject )
            newgo.name = "LeftJoystickCanvas"
            self.rootCanvas = KTool.GetComponent(newgo, typeof(Canvas))
            assert( self.rootCanvas )

            DreamSpaceLuaUtils.AlignRectTransform( self.rootCanvas:rectTransform(), parentRectTF )
            ---

            self.leftJoystickTF = newgo.transform:Find("LeftJoystick")
            self.leftJoystickEnv = DreamSpaceLuaUtils.GetLuaScr(self.leftJoystickTF.gameObject, "Game.Behaviours.ETCJoystick" )
            assert( self.leftJoystickEnv )

            ---@type UnityEngine.RectTransform
            local etcJoystickRT = self.leftJoystickTF:GetComponent(typeof(CS.UnityEngine.RectTransform))
            etcJoystickRT:SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, joystickSize)
            etcJoystickRT:SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, joystickSize)
            if position ~= nil then
                etcJoystickRT.anchoredPosition3D = position
            end
        else
            printError( "加载 LeftJoystickCanvas.prefab 失败" )
        end 
    end 
end




-- 若是找到, 就销毁之
function LeftJoystickCanvasMgr:CheckAndRemove()
    if isNotNull(self.rootCanvas) then 
        Object.Destroy( self.rootCanvas.gameObject )
    end 
    self.rootCanvas = nil
end


function LeftJoystickCanvasMgr:GetLeftJoystick()    
    return self.leftJoystickEnv
end



function LeftJoystickCanvasMgr:Show( isShow )  
    self:CheckOrInitSync()
    if isNotNull(self.leftJoystickTF) then 
        local alpha = isShow==true and 1.0 or 0.0
        CfUtils.SetCanvasGroupAlpha(self.leftJoystickTF.gameObject, alpha )
        CfUtils.SetCanvasGroupInteractable(self.leftJoystickTF.gameObject, isShow )
    else 
        printError("异常, 没找到 leftJoystickTF")
    end 
end



return LeftJoystickCanvasMgr
